// lazy modules: the 3D studios load the first time they open
const lazy={flatpack:()=>import('./flatpack.js'),game:()=>import('./game.js')},loaded={};
function ensureModule(id){if(lazy[id]&&!loaded[id]){loaded[id]=lazy[id]().catch(e=>{console.warn('studio failed to load',id,e);const host=$(id==='game'?'gameHost':'flatpackHost');if(host)host.innerHTML='<p class="feedback-box">This studio could not load in this browser. Try reloading the page.</p>'})}}

// accessible studio tabs
function selectTool(id,focus=false,scroll=false){const tab=tabs.find(t=>t.dataset.tool===id);if(!tab)return;
  tabs.forEach(t=>{const on=t===tab;t.setAttribute('aria-selected',String(on));t.tabIndex=on?0:-1;$('panel-'+t.dataset.tool).hidden=!on});
  if(focus)tab.focus();const nav=tab.parentElement;
  if(nav.scrollWidth>nav.clientWidth+2)nav.scrollTo({left:tab.offsetLeft-nav.clientWidth/2+tab.clientWidth/2,behavior:REDUCED()?'auto':'smooth'});
  history.replaceState(null,'','#'+id);ensureModule(id);onStudioShown(id);window.dispatchEvent(new Event('resize'));
  if(scroll)$('workspace').scrollIntoView({behavior:REDUCED()?'auto':'smooth',block:'start'})}
tabs.forEach((t,i)=>{t.addEventListener('click',()=>selectTool(t.dataset.tool));t.addEventListener('keydown',e=>{if(!['ArrowDown','ArrowUp','ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();let n=i;if(e.key==='Home')n=0;else if(e.key==='End')n=tabs.length-1;else n=(i+(['ArrowDown','ArrowRight'].includes(e.key)?1:-1)+tabs.length)%tabs.length;selectTool(tabs[n].dataset.tool,true)})});
$('heroApps').addEventListener('click',e=>{const a=e.target.closest('[data-go]');if(!a)return;e.preventDefault();selectTool(a.dataset.go,false,true)});
function onStudioShown(id){if(id==='body')bodyFlow()}

