function cr(P,n=8){const o=[];for(let i=0;i<P.length-1;i++){const p0=P[i-1]||P[i],p1=P[i],p2=P[i+1],p3=P[i+2]||P[i+1];
  for(let k=0;k<n;k++){const t=k/n,t2=t*t,t3=t2*t,f=j=>.5*(2*p1[j]+(-p0[j]+p2[j])*t+(2*p0[j]-5*p1[j]+4*p2[j]-p3[j])*t2+(-p0[j]+3*p1[j]-3*p2[j]+p3[j])*t3);o.push([f(0),f(1)])}}o.push(P[P.length-1]);return o}
const HX=lon=>22+(lon-166)*22.6,HY=lat=>14+(lat-34)*29.6;
const landPath=P=>cr(P.concat([P[0],P[1]]),6).map((p,i)=>(i?'L':'M')+HX(p[0]).toFixed(1)+','+HY(p[1]).toFixed(1)).join('')+'Z';
const LAND=[landPath(NI),landPath(SI),landPath(RK)];
function pin(x,y){return `<g class="hm-pin"><ellipse cx="${x+3}" cy="${y+1.5}" rx="7" ry="2.2" fill="#1B2452" opacity=".22"/><path d="M${x},${y} c-2.6,-7 -9.5,-11 -9.5,-17.5 a9.5,9.5 0 1 1 19,0 c0,6.5 -6.9,10.5 -9.5,17.5z" fill="var(--tint)" stroke="${C.ink}" stroke-width="1.6"/><circle cx="${x}" cy="${y-17.5}" r="3.6" fill="#fff" stroke="${C.ink}" stroke-width="1.2"/></g>`}
let historyIndex=0;const inquiry=[];
function renderHistoryMap(){const h=historyMoments[historyIndex];let o=`<rect x="10" y="4" width="320" height="428" rx="16" class="hm-sea"/>`;
  for(let la=36;la<=46;la+=2)o+=`<line class="hm-grid" x1="10" x2="330" y1="${HY(la)}" y2="${HY(la)}"/><text class="hm-lab" x="16" y="${HY(la)-4}">${la}°S</text>`;
  for(let lo=168;lo<=178;lo+=2)o+=`<line class="hm-grid" y1="4" y2="432" x1="${HX(lo)}" x2="${HX(lo)}"/>`;
  o+=LAND.map(d=>`<path class="hm-land${h.all?' lit':''}" d="${d}"/>`).join('');
  o+=`<text class="hm-lab" x="${HX(168.1)}" y="${HY(37.2)}">TE IKA-A-MĀUI</text><text class="hm-lab" x="${HX(168.1)}" y="${HY(37.2)+13}" style="letter-spacing:.02em">North Island</text>`;
  o+=`<text class="hm-lab" x="${HX(174.2)}" y="${HY(44.6)}">TE WAIPOUNAMU</text><text class="hm-lab" x="${HX(174.2)}" y="${HY(44.6)+13}" style="letter-spacing:.02em">South Island</text>`;
  o+=`<text class="hm-lab" x="${HX(168.6)}" y="${HY(47.5)}">RAKIURA</text>`;
  if(h.all){const tx=HX(177.6),ty=HY(36.6),cx=300,cy=40,bx=cx-tx,by=cy-ty,bl=Math.hypot(bx,by),ux=bx/bl,uy=by/bl,head=s=>{const c=Math.cos(s),n=Math.sin(s);return [(tx+10*(ux*c-uy*n)).toFixed(1),(ty+10*(ux*n+uy*c)).toFixed(1)]};
    o+=`<path class="hm-arrow" d="M326 26 Q${cx} ${cy} ${tx} ${ty}"/><path d="M${head(.5).join(' ')} L${tx} ${ty} L${head(-.5).join(' ')}" fill="none" stroke="var(--deep)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/><text class="hm-place2" x="322" y="18" text-anchor="end">from East Polynesia</text>`}
  // the other moments' places, small and clickable
  historyMoments.forEach((m,i)=>{if(i===historyIndex)return;m.places.slice(0,1).forEach(p=>{const x=HX(p.lon),y=HY(p.lat);o+=`<g class="hm-other" data-history="${i}" style="cursor:pointer"><circle class="hm-dot" cx="${x}" cy="${y}" r="5"/><text class="hm-place2" x="${x+(p.dx<0?-9:9)}" y="${y+4}" ${p.dx<0?'text-anchor="end"':''}>${esc(m.short)}</text></g>`})});
  h.places.forEach(p=>{const x=HX(p.lon),y=HY(p.lat);o+=pin(x,y);const tx=x+(p.dx<0?-14:14),ty=y-14+(p.dy||0),anc=p.dx<0?' text-anchor="end"':'';
    o+=`<text class="hm-place" x="${tx}" y="${ty}"${anc}>${esc(p.n)}</text>${p.e?`<text class="hm-place2" x="${tx}" y="${ty+13}"${anc}>${esc(p.e)}</text>`:''}`});
  $('historyMap').innerHTML=o}
function renderHistory(){const h=historyMoments[historyIndex];$('historyYear').innerHTML=`<span>${esc(h.year)}</span>`;$('historyTitle').textContent=h.title;$('historyText').textContent=h.text;$('historyPlace').textContent=h.place;$('historyQuestion').textContent=h.question;$('historySource').href=h.source;$('historySourceName').textContent=h.sourceName;
  $$('#historyTimeline button').forEach((b,i)=>b.setAttribute('aria-current',String(i===historyIndex)));
  $('historyMap').setAttribute('aria-label',`Schematic map of Aotearoa New Zealand with a simplified coastline. ${h.places.length?'Marked: '+h.places.map(p=>p.n+(p.e?' ('+p.e+')':'')).join(', ')+'.':'The whole country is shaded: every rohe has its own histories.'}`);
  renderHistoryMap()}
$('historyTimeline').innerHTML=historyMoments.map((h,i)=>`<li><button type="button" data-history="${i}" aria-label="${esc(h.year)}: ${esc(h.tag)}"><i>${i+1}</i><b>${esc(h.short)}</b><small>${esc(h.tag)}</small></button></li>`).join('');
const pickHistory=e=>{const b=e.target.closest('[data-history]');if(b){historyIndex=+b.dataset.history;renderHistory()}};
$('historyTimeline').addEventListener('click',pickHistory);$('historyMap').addEventListener('click',pickHistory);renderHistory();
$('saveHistory').addEventListener('click',()=>{const note=$('historyNote').value.trim();if(!note){$('historyNote').focus();return}inquiry.push({moment:historyMoments[historyIndex].year,note});$('historyNote').value='';$('historyLog').innerHTML=inquiry.map(n=>`<li><b>${esc(n.moment)}</b> · ${esc(n.note)}</li>`).join('')});
$('downloadHistory').addEventListener('click',()=>download('my-place-inquiry.txt',inquiry.length?inquiry.map(n=>`${n.moment}\n${n.note}\n`).join('\n'):'No inquiry notes added yet.'));

/* ---------------------------------------------------------------- pinhole camera optics */
// A ray model. Object 1.5 m tall, 2 m from the pinhole. Image height = 1.5 m × v / 2 m; blur on the screen ≈ d × (1 + v/u);
// brightness on the screen ∝ d² / v² (light let in ÷ area it spreads over). All shown relative to a 6 mm hole and a 60 mm screen.
const pin2=$('pinholeCanvas'),pc=pin2.getContext('2d');
function drawObj(g,type,H,col){g.save();if(type==='tree'){g.fillStyle=col?col.trunk:C.dPeach;g.strokeStyle=C.ink;g.lineWidth=Math.max(1,H*.012);g.beginPath();g.moveTo(-H*.05,0);g.lineTo(-H*.035,-H*.5);g.lineTo(H*.035,-H*.5);g.lineTo(H*.05,0);g.closePath();g.fill();if(!col)g.stroke();
    const blobs=[[0,-.74,.22],[-.17,-.58,.17],[.17,-.6,.17],[-.1,-.86,.15],[.11,-.84,.14]];g.fillStyle=col?col.leaf:C.land;
    blobs.forEach(([x,y,r])=>{g.beginPath();g.arc(x*H,y*H,r*H,0,Math.PI*2);g.fill();if(!col)g.stroke()});blobs.forEach(([x,y,r])=>{g.beginPath();g.arc(x*H,y*H,r*H-g.lineWidth,0,Math.PI*2);g.fill()});g.fillStyle=col?'rgba(255,255,255,.18)':'#A4D47E';g.beginPath();g.arc(-.05*H,-.8*H,.08*H,0,Math.PI*2);g.fill()}
  else if(type==='bike'){g.strokeStyle=col?col.frame:C.straw;g.lineWidth=H*.05;g.lineCap='round';g.lineJoin='round';const r=H*.24;[-.36,.36].forEach(x=>{g.beginPath();g.arc(x*H,-r,r,0,Math.PI*2);g.stroke()});
    g.beginPath();g.moveTo(-.36*H,-r);g.lineTo(-.08*H,-H*.72);g.lineTo(.05*H,-r);g.lineTo(-.36*H,-r);g.moveTo(.05*H,-r);g.lineTo(.26*H,-H*.72);g.lineTo(-.08*H,-H*.72);g.moveTo(.26*H,-H*.72);g.lineTo(.36*H,-r);g.moveTo(.26*H,-H*.72);g.lineTo(.22*H,-H*.92);g.lineTo(.36*H,-H*.92);g.moveTo(-.12*H,-H*.78);g.lineTo(-.02*H,-H*.78);g.stroke()}
  else{g.fillStyle=col?col.letter:C.dLav;g.font=`700 ${H*1.25}px Fredoka, sans-serif`;g.textAlign='center';g.textBaseline='alphabetic';g.fillText('A',0,0)}
  g.restore()}
function rr(g,x,y,w,h,r){g.beginPath();g.moveTo(x+r,y);g.arcTo(x+w,y,x+w,y+h,r);g.arcTo(x+w,y+h,x,y+h,r);g.arcTo(x,y+h,x,y,r);g.arcTo(x,y,x+w,y,r);g.closePath()}
function drawPinhole(){const narrow=(pin2.parentElement.clientWidth||760)<520;if(narrow!==(pin2.height>600)){pin2.width=narrow?520:760;pin2.height=narrow?790:460}
  const d=+$('aperture').value,v=+$('screenDistance').value,type=$('pinholeObject').value,w=pin2.width,h=pin2.height,g=pc;
  $('apertureOut').textContent=d+' mm';$('distanceOut').textContent=v+' mm';
  const size=v/60,bright=(d/6)**2*(60/v)**2;$('pinholeSize').textContent=`Inverted · ${size.toFixed(2)}× size`;$('pinholeLight').textContent=(bright>=10?bright.toFixed(0):bright.toFixed(bright<1?2:1))+'×';
  g.clearRect(0,0,w,h);g.fillStyle='#FFFFFF';rr(g,0,0,w,h,14);g.fill();
  g.strokeStyle='#EEF3F8';g.lineWidth=1;for(let x=20;x<w;x+=30){g.beginPath();g.moveTo(x,0);g.lineTo(x,h);g.stroke()}for(let y=20;y<h;y+=30){g.beginPath();g.moveTo(0,y);g.lineTo(w,y);g.stroke()}
  const axis=230,ox=88,H=170,px=250,sx=px+v*2.25,hole=Math.max(1.6,d*.9),boxT=axis-120,boxB=axis+120;
  // ground and object
  g.strokeStyle=C.line2;g.lineWidth=2;g.beginPath();g.moveTo(20,axis+H/2+2);g.lineTo(200,axis+H/2+2);g.stroke();
  g.save();g.translate(ox,axis+H/2);drawObj(g,type,H);g.restore();
  // camera box: dark inside, ink walls, a gap for the pinhole
  g.fillStyle='#2B3260';rr(g,px,boxT,sx-px+10,boxB-boxT,10);g.fill();
  g.fillStyle=C.ink;g.fillRect(px-6,boxT,sx-px+16,7);g.fillRect(px-6,boxB-7,sx-px+16,7);g.fillRect(px-6,boxT,12,axis-hole-boxT);g.fillRect(px-6,axis+hole,12,boxB-axis-hole);
  // light cones from the top and bottom of the object through the hole to the screen (their spread is the blur)
  const top=[ox,axis-H/2+6],bot=[ox,axis+H/2-4];
  [[top,'rgba(232,104,138,'],[bot,'rgba(111,163,232,']].forEach(([P,c])=>{const a=[px,axis-hole],b=[px,axis+hole];const k=(sx-px)/(px-P[0]);
    const ya=a[1]+(a[1]-P[1])*k,yb=b[1]+(b[1]-P[1])*k;g.fillStyle=c+'.16)';g.beginPath();g.moveTo(P[0],P[1]);g.lineTo(a[0],a[1]);g.lineTo(b[0],b[1]);g.closePath();g.fill();
    g.fillStyle=c+'.42)';g.beginPath();g.moveTo(a[0],a[1]);g.lineTo(sx,ya);g.lineTo(sx,yb);g.lineTo(b[0],b[1]);g.closePath();g.fill();
    g.strokeStyle=c+'.9)';g.lineWidth=1.6;g.beginPath();g.moveTo(P[0],P[1]);g.lineTo(px,axis);g.lineTo(sx,axis+(axis-P[1])*k);g.stroke();
    g.fillStyle=c+'1)';g.fillRect(sx-4,Math.min(ya,yb),5,Math.abs(yb-ya)+1)});
  g.fillStyle='#F3EEE4';g.fillRect(sx,boxT+8,7,boxB-boxT-16);
  g.fillStyle=C.ink;g.font='500 12px "IBM Plex Mono", monospace';g.textAlign='center';
  g.fillText('OBJECT',ox,axis+H/2+24);g.fillText('PINHOLE',px,boxB+22);g.fillText('SCREEN',sx+4,boxB+22);
  g.fillStyle=C.muted;g.font='500 11px "IBM Plex Mono", monospace';g.fillText(`${d} mm`,px,boxT-10);g.fillText(`${v} mm`,(px+sx)/2,boxB+40);
  g.strokeStyle=C.muted;g.lineWidth=1;g.beginPath();g.moveTo(px,boxB+30);g.lineTo(sx,boxB+30);g.stroke();
  // the screen, seen from behind: translucent paper, darker when less light arrives
  const ix=narrow?24:Math.max(sx+40,522),iw=narrow?w-48:w-ix-20,iy=narrow?520:40,ih=narrow?220:h-90;
  g.fillStyle=C.ink;g.font='600 12px "IBM Plex Mono", monospace';g.textAlign='left';g.fillText('WHAT THE SCREEN SHOWS',ix,iy-12);
  g.fillStyle='#EFE7D8';rr(g,ix,iy,iw,ih,12);g.fill();
  g.save();rr(g,ix,iy,iw,ih,12);g.clip();
  const imgH=1500*v/2000*(narrow?2.6:3.1),blur=d*(1+v/2000)*.7;
  g.translate(ix+iw/2,iy+ih/2);g.rotate(Math.PI);g.translate(0,imgH/2);g.filter=`blur(${blur.toFixed(1)}px)`;
  drawObj(g,type,imgH,{trunk:'#C9733F',leaf:'#7DBA55',frame:'#D9577B',letter:'#7B61C9'});g.filter='none';g.restore();
  const lit=clamp(.72+.2*Math.log2(bright),.08,1);g.fillStyle=`rgba(20,24,52,${(.8*(1-lit)).toFixed(3)})`;rr(g,ix,iy,iw,ih,12);g.fill();
  g.strokeStyle=C.ink;g.lineWidth=2;rr(g,ix,iy,iw,ih,12);g.stroke();
  g.fillStyle=C.muted;g.font='500 11px "IBM Plex Mono", monospace';g.fillText('UPSIDE DOWN AND BACK TO FRONT',ix,iy+ih+20);
  g.fillText('SCHEMATIC · NOT TO SCALE',22,narrow?470:h-14);
  $('pinholeExplain').textContent=d>12?'A wider hole lets in more light, but each point of the object spreads into a bigger blob, so the image goes soft. Try a smaller hole for a sharper, dimmer image.':v>75?'A longer box makes the image bigger, but the same light is spread over a bigger area, so it gets dimmer.':'A small hole keeps each blob of light small: sharper, but dimmer. Change one thing at a time when you compare.'}
['aperture','screenDistance','pinholeObject'].forEach(id=>$(id).addEventListener('input',drawPinhole));
let redrawT=0;window.addEventListener('resize',()=>{clearTimeout(redrawT);redrawT=setTimeout(()=>{drawPinhole();renderMarket()},120)});
if(document.fonts&&document.fonts.ready)document.fonts.ready.then(drawPinhole);drawPinhole();
$('pinholeChallenge').addEventListener('click',()=>{$('pinholeQuestion').textContent='Investigation: predict what happens when you double the hole and keep the screen distance the same. Record brightness and sharpness, then explain it with the rays.'});

/* ---------------------------------------------------------------- pop-art collage */
let collageItems=[],collageSerial=0,dragItem=null;
const SWATCH=[['Navy',C.ink],['Strawberry',C.straw],['Sky',C.dSky],['Mint',C.dMint],['Peach','#F49A5E'],['Lavender',C.dLav],['Blush',C.blush]];
$('collageSwatches').innerHTML=SWATCH.map(([n,c],i)=>`<button type="button" role="radio" aria-checked="${i===0}" aria-label="${n}" style="--sw:${c}" data-c="${c}"></button>`).join('');
$('collageSwatches').append($('collageColour'));
$('collageSwatches').addEventListener('click',e=>{const b=e.target.closest('[data-c]');if(!b)return;$('collageColour').value=b.dataset.c;$$('#collageSwatches button').forEach(x=>x.setAttribute('aria-checked',String(x===b)))});
$('collageColour').addEventListener('input',()=>$$('#collageSwatches button').forEach(x=>x.setAttribute('aria-checked',String(x.dataset.c.toLowerCase()===$('collageColour').value.toLowerCase()))));
function starPath(cx,cy,r){let p='';for(let i=0;i<10;i++){const a=-Math.PI/2+i*Math.PI/5,q=i%2?r*.43:r;p+=`${i?'L':'M'}${(cx+Math.cos(a)*q).toFixed(1)},${(cy+Math.sin(a)*q).toFixed(1)}`}return p+'Z'}
function shapeMarkup(item){const {type,size:s,colour}=item,st=`stroke="${C.ink}" stroke-width="3" stroke-linejoin="round"`;if(type==='circle')return `<circle r="${s/2}" fill="${colour}" ${st}/>`;if(type==='heart')return `<path d="M0 ${s*.38}C${-s*.8} ${-s*.1} ${-s*.35} ${-s*.65} 0 ${-s*.25}C${s*.35} ${-s*.65} ${s*.8} ${-s*.1} 0 ${s*.38}Z" fill="${colour}" ${st}/>`;if(type==='bolt')return `<path d="M${s*.12} ${-s*.6}L${-s*.35} ${s*.08}H${-s*.02}L${-s*.15} ${s*.6}L${s*.4} ${-s*.14}H${s*.05}Z" fill="${colour}" ${st}/>`;if(type==='letter')return `<text y="${s*.36}" text-anchor="middle" font-family="Fredoka, sans-serif" font-weight="700" font-size="${s}" fill="${colour}" stroke="${C.ink}" stroke-width="2.5" paint-order="stroke">A</text>`;return `<path d="${starPath(0,0,s/2)}" fill="${colour}" ${st}/>`}
function renderCollage(){const board=$('collageBoard');$$('.collage-item',board).forEach(n=>n.remove());collageItems.forEach((it,i)=>{const ns='http://www.w3.org/2000/svg',g=document.createElementNS(ns,'g');g.setAttribute('class','collage-item');g.setAttribute('transform',`translate(${it.x} ${it.y}) rotate(${it.rot})`);g.dataset.index=i;g.innerHTML=shapeMarkup(it);board.appendChild(g)});$('collageTitle').textContent=$('collageText').value||'YOUR BIG IDEA';$('collageSizeOut').textContent=$('collageSize').value}
$('collageText').addEventListener('input',renderCollage);$('collageSize').addEventListener('input',renderCollage);
$('addCollage').addEventListener('click',()=>{const n=collageSerial++;collageItems.push({type:$('collageSymbol').value,size:+$('collageSize').value,colour:$('collageColour').value,x:120+(n*137)%460,y:90+(n*83)%260,rot:(n*23)%50-25});renderCollage()});
$('undoCollage').addEventListener('click',()=>{collageItems.pop();renderCollage()});$('clearCollage').addEventListener('click',()=>{collageItems=[];renderCollage()});
function svgPoint(e){const p=$('collageBoard').createSVGPoint();p.x=e.clientX;p.y=e.clientY;return p.matrixTransform($('collageBoard').getScreenCTM().inverse())}
$('collageBoard').addEventListener('pointerdown',e=>{const g=e.target.closest('.collage-item');if(!g)return;dragItem=+g.dataset.index;$('collageBoard').setPointerCapture(e.pointerId);e.preventDefault()});$('collageBoard').addEventListener('pointermove',e=>{if(dragItem===null)return;const p=svgPoint(e);collageItems[dragItem].x=clamp(p.x,35,665);collageItems[dragItem].y=clamp(p.y,35,420);renderCollage()});$('collageBoard').addEventListener('pointerup',()=>dragItem=null);
$('downloadCollage').addEventListener('click',()=>{const copy=$('collageBoard').cloneNode(true);copy.setAttribute('xmlns','http://www.w3.org/2000/svg');download('my-pop-collage.svg','<?xml version="1.0" encoding="UTF-8"?>\n'+new XMLSerializer().serializeToString(copy),'image/svg+xml')});
[['star',C.ink],['heart',C.straw],['bolt','#F49A5E'],['circle',C.dSky]].forEach(([t,c],i)=>{collageItems.push({type:t,size:[80,90,100,60][i],colour:c,x:[150,330,500,600][i],y:[120,250,150,330][i],rot:[-12,8,14,0][i]});collageSerial++});renderCollage();

/* ---------------------------------------------------------------- habitat model */
const species={kakapo:{name:'KĀKĀPŌ',needs:{space:70,shade:75,water:45,enrichment:80,quiet:85},note:'Real kākāpō live only on protected predator-free islands and in one fenced mainland sanctuary, and the public cannot visit them (Department of Conservation). This is a design exercise, not a zoo plan.',src:'https://www.doc.govt.nz/nature/native-animals/birds/birds-a-z/kakapo/habitat-and-islands/'},
  tuatara:{name:'TUATARA',needs:{space:55,shade:60,water:35,enrichment:65,quiet:75}},
  giraffe:{name:'GIRAFFE',needs:{space:95,shade:50,water:75,enrichment:75,quiet:50}}};
const controlNames={space:'Usable space',shade:'Shelter + shade',water:'Water access',enrichment:'Enrichment',quiet:'Quiet retreat'};
const zooStart=[70,60,50,65,70];
function buildZooControls(){$('zooControls').innerHTML=Object.entries(controlNames).map(([key,name],i)=>`<label class="zoo-control range-row" for="zoo-${key}"><span>${name}</span><output id="zoo-${key}-out">${zooStart[i]}</output><input id="zoo-${key}" data-zoo="${key}" type="range" min="0" max="100" value="${zooStart[i]}"></label>`).join('');
  $$('[data-zoo]').forEach(r=>r.addEventListener('input',()=>{$(r.id+'-out').textContent=r.value;drawZoo();$('zooScore').textContent='—';$('zooMeter').style.width='0';$('zooFeedback').textContent='Design changed. Test again to compare with the illustrative targets.'}))}
const zv=k=>+$('zoo-'+k).value;
function tree(x,y,s){return `<g transform="translate(${x} ${y}) scale(${s})"><rect x="-4" y="-34" width="8" height="34" rx="3" fill="${C.dPeach}" stroke="${C.ink}" stroke-width="1.5"/><circle cx="-12" cy="-44" r="18" fill="${C.land}" stroke="${C.ink}" stroke-width="1.5"/><circle cx="10" cy="-50" r="22" fill="#9BD06F" stroke="${C.ink}" stroke-width="1.5"/></g>`}
function animal(sp){const st=`stroke="${C.ink}" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"`;
  if(sp==='kakapo')return `<g transform="translate(330 352)"><ellipse cx="4" cy="2" rx="46" ry="7" fill="#1B2452" opacity=".14"/><path d="M-6 -2 l-6 8 M8 -2 l4 8" ${st} fill="none"/><path d="M-44 -30c0-24 22-40 46-38 22 2 34 18 34 36 0 20-18 32-40 32-24 0-40-12-40-30z" fill="#8DBB5A" ${st}/><path d="M-30 -36c8-6 18-6 26 0M-34 -22c10-6 22-6 30 0M-24 -10c8-4 16-4 22 0" fill="none" stroke="#5E8E3A" stroke-width="2" stroke-linecap="round"/><circle cx="26" cy="-46" r="20" fill="#C9D98A" ${st}/><path d="M40 -44c8 0 12 6 8 12-4 2-8 0-10-4z" fill="#F4ECD8" ${st}/><circle cx="30" cy="-50" r="3.4" fill="${C.ink}"/></g>`;
  if(sp==='tuatara')return `<g transform="translate(320 360)"><ellipse cx="0" cy="2" rx="70" ry="7" fill="#1B2452" opacity=".14"/><path d="M-30 -8 l-10 10 M-6 -8 l-4 10 M24 -8 l6 10 M40 -8 l10 10" ${st} fill="none"/><path d="M-90 -6c20-4 40-8 56-20 20-12 50-12 72-4 14 4 24 0 34-6 6 6 6 14-2 20-12 10-34 12-52 12-30 2-70 2-108-2z" fill="#9AA27A" ${st}/><path d="M-30 -24 l4 -9 4 8 4 -9 4 8 4 -9 4 8 4 -9 4 8 4 -9 4 8" fill="#FFF8EC" ${st}/><circle cx="58" cy="-12" r="3" fill="${C.ink}"/></g>`;
  return `<g transform="translate(320 366)"><ellipse cx="0" cy="2" rx="60" ry="7" fill="#1B2452" opacity=".14"/><path d="M-34 -40 v40 M-20 -40 v40 M22 -40 v40 M36 -40 v40" stroke="${C.ink}" stroke-width="9" stroke-linecap="round"/><path d="M-34 -40 v40 M-20 -40 v40 M22 -40 v40 M36 -40 v40" stroke="#F2C27A" stroke-width="5" stroke-linecap="round"/><path d="M-46 -52c0-14 12-22 30-22h40c16 0 26 8 26 20 0 12-10 18-26 18h-44c-16 0-26-4-26-16z" fill="#F2C27A" ${st}/><path d="M34 -66 52 -170" stroke="${C.ink}" stroke-width="22" stroke-linecap="round"/><path d="M34 -66 52 -170" stroke="#F2C27A" stroke-width="17" stroke-linecap="round"/><path d="M42 -176c6-10 26-10 34 0 4 6 0 12-8 12h-22c-6 0-8-6-4-12z" fill="#F2C27A" ${st}/><path d="M48 -180 v-10 M58 -180 v-10" ${st}/><circle cx="60" cy="-172" r="2.6" fill="${C.ink}"/><g fill="${C.dPeach}" opacity=".75"><circle cx="-24" cy="-58" r="6"/><circle cx="-4" cy="-50" r="5"/><circle cx="14" cy="-62" r="6"/><circle cx="40" cy="-110" r="4.5"/><circle cx="46" cy="-140" r="4"/><circle cx="-34" cy="-46" r="4"/></g></g>`}
function drawZoo(){const sp=$('zooSpecies').value,S=species[sp],space=zv('space'),shade=zv('shade'),water=zv('water'),enr=zv('enrichment'),quiet=zv('quiet');
  const W=300+space*3.4,L=350-W/2,R=350+W/2,top=132,bot=404;let o='';
  o+=`<rect width="700" height="440" fill="#F4FBF7"/><path d="M0 128 Q120 84 240 108 T470 98 T700 108 V440 H0z" fill="#DDF1E5"/>`;
  o+=`<rect x="0" y="${top+6}" width="700" height="${440-top}" fill="#E7F2DA"/>`;
  o+=`<rect x="${L}" y="${top}" width="${W}" height="${bot-top}" rx="22" fill="#CFE8B8" stroke="${C.ink}" stroke-width="2"/>`;
  // quiet retreat: a dense planted screen along one side
  const qw=quiet*1.1;if(qw>4)o+=`<rect x="${L+10}" y="${top+12}" width="${qw}" height="${bot-top-24}" rx="14" fill="#9FCB82" stroke="${C.ink}" stroke-width="1.5" stroke-dasharray="4 4"/>${Array.from({length:Math.floor((bot-top-40)/26)},(_,i)=>`<circle cx="${L+10+qw/2}" cy="${top+34+i*26}" r="${Math.min(10,qw/3)}" fill="#86BE6C"/>`).join('')}${quiet>30?`<text class="zoo-t" x="${L+18}" y="${top+30}">QUIET</text>`:''}`;
  // shade: trees along the back, plus a shelter that grows
  const nTrees=Math.round(shade/22);for(let i=0;i<nTrees;i++)o+=tree(L+qw+46+i*(W-qw-190)/Math.max(1,nTrees-1||1),top+78,.95+((i*37)%5)/10);
  const hs=.6+shade/160;o+=`<g transform="translate(${R-70} ${top+120}) scale(${hs})"><rect x="-40" y="-38" width="80" height="44" rx="6" fill="#FFF8EC" stroke="${C.ink}" stroke-width="2"/><path d="M-52 -36 0 -72 52 -36z" fill="${C.peach}" stroke="${C.ink}" stroke-width="2" stroke-linejoin="round"/><rect x="-12" y="-20" width="24" height="26" rx="4" fill="#2B3260"/></g>`;
  // water
  if(water>2)o+=`<ellipse cx="${R-90}" cy="${bot-38}" rx="${16+water*.9}" ry="${8+water*.22}" fill="${C.sky}" stroke="${C.dSky}" stroke-width="2"/>`;
  // enrichment: logs, rocks and a feeder
  const items=Math.round(enr/20),slots=[L+qw+44,L+qw+92,R-200,R-152,L+qw+140].filter(x=>x<250||x>420);for(let i=0;i<Math.min(items,slots.length);i++){const x=slots[i],y=bot-28-(i%2)*16;o+=i%3===0?`<rect x="${x-22}" y="${y-9}" width="44" height="16" rx="8" fill="#D9A27A" stroke="${C.ink}" stroke-width="1.6"/><circle cx="${x+15}" cy="${y-1}" r="4" fill="none" stroke="${C.ink}" stroke-width="1.2"/>`:i%3===1?`<ellipse cx="${x}" cy="${y}" rx="18" ry="11" fill="#D8D3E6" stroke="${C.ink}" stroke-width="1.6"/>`:`<path d="M${x} ${y+6} v-40" stroke="${C.ink}" stroke-width="3"/><rect x="${x-10}" y="${y-44}" width="20" height="12" rx="3" fill="${C.butter}" stroke="${C.ink}" stroke-width="1.6"/>`}
  // fence posts
  for(let x=L+20;x<R-10;x+=34)o+=`<path d="M${x} ${top-8} v14" stroke="${C.ink}" stroke-width="2.4" stroke-linecap="round"/>`;
  o+=animal(sp);
  o+=`<rect x="${350-92}" y="${bot+8}" width="184" height="20" rx="10" fill="#fff" stroke="${C.line2}"/><text class="zoo-t" x="350" y="${bot+22}" text-anchor="middle">${S.name} · HABITAT MODEL</text>`;
  $('zooScene').innerHTML=o;
  $('zooNote').innerHTML=S.note?`${esc(S.note)} <a href="${S.src}" target="_blank" rel="noopener">DOC: kākāpō habitat ↗</a>`:'The targets in this model are made up for learning. Real habitats are designed with species experts and vets.'}
buildZooControls();drawZoo();
$('zooSpecies').addEventListener('change',()=>{drawZoo();$('zooScore').textContent='—';$('zooMeter').style.width='0';$('zooFeedback').textContent='Species changed. Test the same design again and notice the different needs.'});
$('zooRun').addEventListener('click',()=>{const s=species[$('zooSpecies').value],vals={};Object.keys(s.needs).forEach(k=>vals[k]=zv(k));const gaps=Object.keys(s.needs).map(k=>({key:k,diff:vals[k]-s.needs[k]}));const score=Math.max(0,Math.round(100-gaps.reduce((a,g)=>a+Math.abs(g.diff),0)/5));$('zooScore').textContent=score+'/100';$('zooMeter').style.width=score+'%';gaps.sort((a,b)=>Math.abs(b.diff)-Math.abs(a.diff));$('zooFeedback').innerHTML=`<b>${score>=85?'Strong model fit':score>=65?'Promising, with trade-offs':'Redesign the conditions'}</b><br>${gaps.slice(0,2).map(g=>`${controlNames[g.key]} is ${Math.abs(g.diff)} points ${g.diff<0?'below':'above'} this model’s target`).join('. ')}. A high score cannot replace species-specific expertise, veterinary care or watching how the animals actually behave.`});

/* ---------------------------------------------------------------- weather observations */
const weather=[];
$('weatherForm').addEventListener('submit',e=>{e.preventDefault();weather.push({time:new Date().toLocaleString('en-NZ'),place:$('weatherPlace').value.trim(),cloud:$('weatherCloud').value,wind:$('weatherWind').value,temp:$('weatherTemp').value,rain:$('weatherRain').value});$('weatherRows').innerHTML=weather.map(o=>`<tr><td>${esc(o.time)}</td><td>${esc(o.place)}</td><td>${esc(o.cloud)}</td><td>${esc(o.wind)}</td><td>${esc(o.temp)}°C</td><td>${esc(o.rain)}</td></tr>`).join('')});
$('downloadWeather').addEventListener('click',()=>download('weather-observations.csv',csv([['Time','Place','Cloud','Wind','Temperature C','Rain'],...weather.map(o=>[o.time,o.place,o.cloud,o.wind,o.temp,o.rain])]),'text/csv'));
$('clearWeather').addEventListener('click',()=>{weather.length=0;$('weatherRows').innerHTML='<tr><td colspan="6">No observations yet. Add your own rather than copying a forecast.</td></tr>'});

/* ---------------------------------------------------------------- made-up market and business transactions */
const prices=[12,14,11,15,17,13,16,18],events=['An ordinary market day. Supply and demand are balanced.','A warm afternoon lifts demand.','A new stall increases supply.','A local event brings more visitors.','Fewer stalls are open, so buyers have fewer choices.','Rain cuts the number of people walking past.','A school group arrives.','The final bell: stock you still hold has an opportunity cost.'];
let market={round:0,cash:100,stock:0};
let MW=620;const MX=i=>52+12+i*(MW-52-28)/7,MY=p=>168-(p-8)/12*146;
function renderMarket(){const svg=$('marketChart'),cw=svg.clientWidth||620;MW=cw&&cw<480?380:620;svg.setAttribute('viewBox',`0 0 ${MW} 200`);const p=prices[market.round];$('marketRound').textContent=market.round+1;$('marketPrice').textContent=money(p);$('marketCash').textContent=money(market.cash);$('marketStock').textContent=market.stock;$('marketEquity').textContent=money(market.cash+market.stock*p);$('marketEvent').textContent=events[market.round];$('buyMarket').disabled=market.cash<p||market.round===7;$('sellMarket').disabled=market.stock<1;$('nextMarket').disabled=market.round===7;
  const pts=prices.slice(0,market.round+1).map((v,i)=>[MX(i),MY(v)]);let o='';
  [10,14,18].forEach(v=>{o+=`<line class="mk-grid" x1="52" x2="${MW-16}" y1="${MY(v)}" y2="${MY(v)}"/><text class="mk-t" x="44" y="${MY(v)+4}" text-anchor="end">$${v}</text>`});
  o+=`<line class="mk-axis" x1="52" x2="${MW-16}" y1="176" y2="176"/>`;
  prices.forEach((_,i)=>{o+=`<text class="mk-t" x="${MX(i)}" y="194" text-anchor="middle" style="${i===market.round?'fill:#222A55;font-weight:600':''}">R${i+1}</text>${i>market.round?`<circle cx="${MX(i)}" cy="176" r="3" fill="${C.line2}"/>`:''}`});
  if(pts.length>1)o+=`<path d="M${pts[0][0]} 176 L${pts.map(q=>q.join(' ')).join(' L')} L${pts[pts.length-1][0]} 176Z" fill="${C.peach}" opacity=".6"/>`;
  o+=`<polyline points="${pts.map(q=>q.join(',')).join(' ')}" fill="none" stroke="${C.ink}" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>`;
  o+=pts.map((q,i)=>`<circle cx="${q[0]}" cy="${q[1]}" r="${i===pts.length-1?7:5}" fill="${i===pts.length-1?C.peach:'#fff'}" stroke="${C.ink}" stroke-width="2"/>`).join('');
  const last=pts[pts.length-1];o+=`<text class="mk-t" x="${last[0]}" y="${last[1]-13}" text-anchor="middle" style="fill:#222A55;font-weight:600">${money(p)}</text><text class="mk-t" x="${MW-16}" y="16" text-anchor="end">MADE-UP PRICES</text>`;
  $('marketChart').innerHTML=o}
$('buyMarket').addEventListener('click',()=>{const p=prices[market.round];if(market.cash>=p){market.cash-=p;market.stock++;$('marketMessage').textContent=`Bought one at ${money(p)}. Cash is now tighter, and stock is not profit until you sell it.`;renderMarket()}});
$('sellMarket').addEventListener('click',()=>{if(market.stock){const p=prices[market.round];market.cash+=p;market.stock--;$('marketMessage').textContent=`Sold one at ${money(p)}. Compare this with what you paid, not just the sale amount.`;renderMarket()}});
$('nextMarket').addEventListener('click',()=>{if(market.round<7){market.round++;$('marketMessage').textContent=market.round===7?`Final position value: ${money(market.cash+market.stock*prices[7])}. Value is not the same as cash in hand.`:'A new round changes the situation. What do you know, and what are you assuming?';renderMarket()}});
$('resetMarket').addEventListener('click',()=>{market={round:0,cash:100,stock:0};$('marketMessage').textContent='Buy before demand rises, but keep enough cash to respond.';renderMarket()});renderMarket();
const transactions=[];
$('txForm').addEventListener('submit',e=>{e.preventDefault();const t={description:$('txDescription').value.trim(),type:$('txType').value,amount:+$('txAmount').value};if(!t.description||!(t.amount>0))return;transactions.push(t);renderTransactions();$('txDescription').value='';$('txDescription').focus()});
function renderTransactions(){const rev=transactions.filter(t=>t.type==='sale').reduce((a,t)=>a+t.amount,0),exp=transactions.filter(t=>t.type==='expense').reduce((a,t)=>a+t.amount,0);$('txRevenue').textContent=money(rev);$('txExpenses').textContent=money(exp);$('txProfit').textContent=money(rev-exp);$('txProfit').style.color=rev-exp<0?'#A83E26':'';$('txList').innerHTML=transactions.length?transactions.map(t=>`<li>${esc(t.description)}<b style="float:right">${t.type==='expense'?'−':'+'}${money(t.amount)}</b></li>`).join(''):'<li>No transactions yet.</li>'}
