/* ---------------------------------------------------------------- video edit decision list (files stay on the device) */
let clips=[],selectedClip=-1,editRun=0;
function selectClip(i){selectedClip=i;const c=clips[i];if(!c)return;$('videoPreview').hidden=false;$('videoPreview').src=c.url;$('trimIn').value=c.in;$('trimOut').value=c.out;$('trimIn').max=c.duration;$('trimOut').max=c.duration;renderClips()}
function renderClips(){$('clipList').innerHTML=clips.length?clips.map((c,i)=>`<button data-clip="${i}" class="${i===selectedClip?'active':''}"><b>${i+1}. ${esc(c.name)}</b><span>${c.in.toFixed(1)}–${c.out.toFixed(1)}s</span><small>${c.duration.toFixed(1)}s original</small><small>${i===selectedClip?'SELECTED':'SELECT'}</small></button>`).join(''):'<p>No clips yet. Add one or more short clips to begin.</p>'}
$('videoFiles').addEventListener('change',async e=>{for(const f of e.target.files){if(!['video/mp4','video/webm','video/quicktime'].includes(f.type))continue;const url=URL.createObjectURL(f),v=document.createElement('video');v.preload='metadata';v.src=url;const duration=await new Promise(resolve=>{v.onloadedmetadata=()=>resolve(Number.isFinite(v.duration)?v.duration:3);v.onerror=()=>resolve(3)});clips.push({name:f.name,url,duration,in:0,out:Math.min(duration,3)});if(selectedClip<0)selectClip(clips.length-1)}renderClips();e.target.value=''});
$('clipList').addEventListener('click',e=>{const b=e.target.closest('[data-clip]');if(b)selectClip(+b.dataset.clip)});
$('applyTrim').addEventListener('click',()=>{const c=clips[selectedClip];if(!c){$('editStatus').textContent='Select a clip first.';return}const a=+$('trimIn').value,b=+$('trimOut').value;if(a<0||b>c.duration||b<=a){$('editStatus').textContent='The trim must start at zero or later and end after the start, inside the clip length.';return}c.in=a;c.out=b;$('editStatus').textContent=`Trim saved for ${c.name}. No video file has been changed.`;renderClips()});
$('moveClip').addEventListener('click',()=>{if(selectedClip<0||selectedClip===clips.length-1)return;[clips[selectedClip],clips[selectedClip+1]]=[clips[selectedClip+1],clips[selectedClip]];selectedClip++;renderClips()});
$('playEdit').addEventListener('click',async()=>{if(!clips.length){$('editStatus').textContent='Add clips before playing the edit.';return}const run=++editRun,v=$('videoPreview');$('editStatus').textContent='Playing your edit decisions…';for(const c of clips){if(run!==editRun)return;v.src=c.url;v.currentTime=c.in;await new Promise(resolve=>{const done=()=>{v.pause();v.ontimeupdate=null;v.onended=null;v.onerror=null;resolve()};v.ontimeupdate=()=>{if(v.currentTime>=c.out)done()};v.onended=done;v.onerror=done;v.play().catch(done)})}$('editStatus').textContent='Preview finished. Download the decisions to keep the sequence.'});
$('downloadEdit').addEventListener('click',()=>download('local-edit-decisions.json',JSON.stringify({format:'assembl local edit decision list',renderedVideo:false,clips:clips.map((c,i)=>({order:i+1,name:c.name,in:c.in,out:c.out}))},null,2),'application/json'));
$('clearEdit').addEventListener('click',()=>{editRun++;clips.forEach(c=>URL.revokeObjectURL(c.url));clips=[];selectedClip=-1;$('videoPreview').pause();$('videoPreview').hidden=true;renderClips()});

// social post checker
$('checkPost').addEventListener('click',()=>{const t=$('socialText').value.trim(),warnings=[],strengths=[];if(!t){$('socialFeedback').textContent='Write a draft first. Nothing will be posted.';return}if(/\b(?:\+64|0\d{1,2})[\d\s-]{6,}/.test(t)||/@/.test(t))warnings.push('Possible contact or personal details: check consent and remove anything that is not needed.');if(/\b(everyone|always|never|guaranteed|proves)\b/i.test(t))warnings.push('Absolute wording may overclaim. What evidence could narrow the claim?');if($('socialAudience').value==='Public')warnings.push('Public audience: check faces, names, location and permission before sharing.');if(t.length<35)warnings.push('Add enough context for the audience to understand the purpose.');if(/\b(we|our|tested|measured|observed|because|source)\b/i.test(t))strengths.push('The draft includes context or evidence language.');if(!warnings.length)strengths.push('No common privacy or overclaiming triggers found. Still ask a person to review it.');$('socialFeedback').innerHTML=`<b>A person still needs to review this</b><ul>${[...warnings,...strengths].map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`});

/* ---------------------------------------------------------------- reaction and movement planning */
let reactionState='idle',reactionTimer=null,reactionStart=0,reactionTimes=[];
$('reactionPad').addEventListener('click',()=>{const pad=$('reactionPad');if(reactionState==='idle'||reactionState==='result'){reactionState='wait';pad.className='reaction-pad';$('reactionLabel').textContent='Wait for green…';reactionTimer=setTimeout(()=>{reactionState='go';reactionStart=performance.now();pad.classList.add('go');$('reactionLabel').textContent='Now! Click!'},1300+(Date.now()%1700))}else if(reactionState==='wait'){clearTimeout(reactionTimer);reactionState='idle';pad.classList.add('too-soon');$('reactionLabel').textContent='Too soon. Start again.'}else if(reactionState==='go'){const ms=Math.round(performance.now()-reactionStart);reactionTimes.push(ms);reactionTimes=reactionTimes.slice(-8);reactionState='result';pad.className='reaction-pad';$('reactionLabel').textContent=ms+' ms. Again?';$('reactionLast').textContent=ms+' ms';$('reactionAverage').textContent=Math.round(reactionTimes.reduce((a,b)=>a+b,0)/reactionTimes.length)+' ms'}});
$('resetReaction').addEventListener('click',()=>{clearTimeout(reactionTimer);reactionTimes=[];reactionState='idle';$('reactionPad').className='reaction-pad';$('reactionLabel').textContent='Start reaction test';$('reactionLast').textContent='—';$('reactionAverage').textContent='—'});
$('sessionPlanner').addEventListener('change',()=>{const selected=$$('#sessionPlanner input:checked'),mins=selected.reduce((a,c)=>a+ +c.value,0),parts=selected.map(c=>c.dataset.part);$('sessionMinutes').textContent=mins+' minutes';$('sessionFill').style.width=Math.min(100,mins/35*100)+'%';$('sessionFeedback').textContent=!parts.includes('Warm-up')?'Add a warm-up that suits the activity.':!parts.includes('Cool-down')?'Think about recovery and water. Needs vary by person and conditions.':mins===30?'A complete 30-minute draft. Ask whether the intensity and activities suit the people taking part.':`${mins} minutes planned. Adjust the blocks to the time you have, rather than treating 30 as a rule.`});$('sessionPlanner').dispatchEvent(new Event('change'));

/* ---------------------------------------------------------------- Web Audio sequencer */
const trackNames=['KICK','CLAP','HAT','TONE'],musicRows=[0,0,0,0].map((_,r)=>Array.from({length:8},(_,s)=>r===0?s%4===0:r===1?s%4===2:r===2?s%2===1:[0,3,6].includes(s)));
let audioCtx=null,musicTimer=null,musicStep=0,presetCount=0;
function renderMusic(){$('musicGrid').innerHTML=musicRows.map((row,r)=>`<div class="music-track"><span>${trackNames[r]}</span>${row.map((on,s)=>`<button class="music-step ${on?'on':''} ${s===(musicStep+7)%8&&musicTimer?'current':''}" data-track="${r}" data-step="${s}" aria-label="${trackNames[r]} step ${s+1}" aria-pressed="${on}"></button>`).join('')}</div>`).join('')}
function sound(r){if(!audioCtx)return;const now=audioCtx.currentTime,g=audioCtx.createGain();g.connect(audioCtx.destination);if(r===2){const len=audioCtx.sampleRate*.045,b=audioCtx.createBuffer(1,len,audioCtx.sampleRate),a=b.getChannelData(0);let seed=42;for(let i=0;i<len;i++){seed=(seed*1664525+1013904223)>>>0;a[i]=(seed/4294967296*2-1)*(1-i/len)}const src=audioCtx.createBufferSource();src.buffer=b;src.connect(g);g.gain.setValueAtTime(.09,now);src.start(now);return}const o=audioCtx.createOscillator();o.connect(g);const freq=r===0?120:r===1?190:220;o.frequency.setValueAtTime(freq,now);if(r===0)o.frequency.exponentialRampToValueAtTime(45,now+.16);else if(r===3)o.frequency.setValueAtTime([220,277,330,392,330,277,440,392][musicStep],now);o.type=r===1?'triangle':'sine';g.gain.setValueAtTime(r===3?.12:.18,now);g.gain.exponentialRampToValueAtTime(.001,now+(r===3?.28:.16));o.start(now);o.stop(now+.3)}
function tickMusic(){musicRows.forEach((row,r)=>{if(row[musicStep])sound(r)});musicStep=(musicStep+1)%8;renderMusic()}
async function toggleMusic(){if(musicTimer){clearInterval(musicTimer);musicTimer=null;$('playMusic').textContent='Play';$('musicStatus').textContent='Paused';renderMusic();return}audioCtx??=new (window.AudioContext||window.webkitAudioContext)();await audioCtx.resume();musicStep=0;musicTimer=setInterval(tickMusic,60000/+$('tempo').value/2);tickMusic();$('playMusic').textContent='Stop';$('musicStatus').textContent='Playing'}
$('playMusic').addEventListener('click',toggleMusic);$('tempo').addEventListener('input',()=>{$('tempoOut').textContent=$('tempo').value+' BPM';if(musicTimer){clearInterval(musicTimer);musicTimer=setInterval(tickMusic,60000/+$('tempo').value/2)}});
$('musicGrid').addEventListener('click',e=>{const b=e.target.closest('.music-step');if(!b)return;const r=+b.dataset.track,s=+b.dataset.step;musicRows[r][s]=!musicRows[r][s];renderMusic();if(musicRows[r][s]){const keep=musicStep;musicStep=s;sound(r);musicStep=keep}});
$('clearMusic').addEventListener('click',()=>{musicRows.forEach(r=>r.fill(false));renderMusic()});$('presetMusic').addEventListener('click',()=>{presetCount++;musicRows.forEach((row,r)=>row.forEach((_,s)=>row[s]=r===0?(s+presetCount)%4===0:r===1?(s+2*presetCount)%4===2:r===2?(s+presetCount)%2===1:(s*3+r+presetCount)%7<2));renderMusic()});renderMusic();

