let wardrobe=[];try{wardrobe=JSON.parse(localStorage.getItem('assembl-next-wardrobe')||'[]');if(!Array.isArray(wardrobe))wardrobe=[]}catch{}let wardrobeFilter='All',outfit=new Set();
function saveWardrobe(){try{localStorage.setItem('assembl-next-wardrobe',JSON.stringify(wardrobe.slice(-60)))}catch{}}
function garmentIcon(cat){if(cat==='Shoes')return '<path d="M8 34c6 0 10-6 14-6 6 4 14 8 24 9 4 1 6 4 6 7v2H6v-6c0-3 1-6 2-6z"/>';if(cat==='Bottom')return '<path d="M16 6h24l4 46H32l-4-28-4 28H12z"/>';if(cat==='Accessory')return '<path d="M12 22h32l-3 28H15z"/><path d="M20 22v-6a8 8 0 0 1 16 0v6" fill="none"/>';if(cat==='Layer')return '<path d="M20 6 6 16l6 12 6-4v28h20V24l6 4 6-12L36 6c-2 4-5 6-8 6s-6-2-8-6z"/><path d="M28 12v40" fill="none"/>';return '<path d="M20 6 6 16l6 12 6-4v28h20V24l6 4 6-12L36 6c-2 4-5 6-8 6s-6-2-8-6z"/>'}
function renderWardrobe(){const items=wardrobe.filter(x=>wardrobeFilter==='All'||x.category===wardrobeFilter);$('wardrobeItems').innerHTML=items.length?items.map(x=>`<article class="wardrobe-card ${outfit.has(x.id)?'outfit':''}"><div class="garment-swatch" style="--swatch:${esc(x.colour)}"><svg viewBox="0 0 56 56" aria-hidden="true">${garmentIcon(x.category)}</svg></div><h5>${esc(x.name)}</h5><p>${esc(x.category).toUpperCase()} · ${money(x.cost)} / ${x.wears} WEARS</p><p>${x.wears?money(x.cost/x.wears)+' PER WEAR':'NOT WORN YET'}</p><div class="button-row"><button class="btn small" data-outfit="${esc(x.id)}">${outfit.has(x.id)?'Remove':'Outfit'}</button><button class="btn small" data-wear="${esc(x.id)}">+ wear</button><button class="btn small quiet" data-delete="${esc(x.id)}" aria-label="Delete ${esc(x.name)}">×</button></div></article>`).join(''):'<div class="wardrobe-empty">No pieces in this view.<br>Add your own, or load the made-up samples.</div>';$('outfitCount').textContent=outfit.size+' pieces selected';const avg=wardrobe.length&&wardrobe.reduce((a,x)=>a+x.wears,0)?wardrobe.reduce((a,x)=>a+x.cost,0)/wardrobe.reduce((a,x)=>a+x.wears,0):null;$('wardrobeInsight').textContent=avg===null?'Add an item or load two examples to explore cost per wear.':`Whole-wardrobe cost per recorded wear: ${money(avg)}. A low number is not the only goal. Comfort, repair, reuse and fit matter too.`}
$('wardrobeForm').addEventListener('submit',e=>{e.preventDefault();const name=$('wardrobeName').value.trim();if(!name)return;wardrobe.push({id:crypto.randomUUID?crypto.randomUUID():String(Date.now()),name,category:$('wardrobeCategory').value,colour:$('wardrobeColour').value,cost:+$('wardrobeCost').value,wears:+$('wardrobeWears').value});saveWardrobe();renderWardrobe();$('wardrobeName').value='';$('wardrobeName').focus()});
$('wardrobeFilters').addEventListener('click',e=>{const b=e.target.closest('[data-category]');if(!b)return;wardrobeFilter=b.dataset.category;$$('#wardrobeFilters button').forEach(x=>x.classList.toggle('selected',x===b));renderWardrobe()});
$('wardrobeItems').addEventListener('click',e=>{const o=e.target.closest('[data-outfit]'),w=e.target.closest('[data-wear]'),d=e.target.closest('[data-delete]');if(o){outfit.has(o.dataset.outfit)?outfit.delete(o.dataset.outfit):outfit.add(o.dataset.outfit)}if(w){const x=wardrobe.find(x=>x.id===w.dataset.wear);if(x)x.wears++}if(d){wardrobe=wardrobe.filter(x=>x.id!==d.dataset.delete);outfit.delete(d.dataset.delete)}saveWardrobe();renderWardrobe()});
$('sampleWardrobe').addEventListener('click',()=>{wardrobe.push({id:'sample-jacket-'+Date.now(),name:'Sample denim jacket',category:'Layer',colour:'#BFDDF5',cost:40,wears:40},{id:'sample-shoes-'+Date.now(),name:'Sample trainers',category:'Shoes',colour:'#F9D2B8',cost:90,wears:90});saveWardrobe();renderWardrobe()});
$('outfitIdea').addEventListener('click',()=>{outfit.clear();['Top','Bottom','Layer','Shoes'].forEach(cat=>{const choices=wardrobe.filter(x=>x.category===cat);if(choices.length)outfit.add(choices[(outfit.size+presetCount)%choices.length].id)});if(!outfit.size&&wardrobe.length)outfit.add(wardrobe[0].id);renderWardrobe()});$('clearOutfit').addEventListener('click',()=>{outfit.clear();renderWardrobe()});
$('downloadWardrobe').addEventListener('click',()=>download('my-wardrobe.csv',csv([['Name','Category','Cost NZD','Wears','Cost per wear'],...wardrobe.map(x=>[x.name,x.category,x.cost,x.wears,x.wears?(x.cost/x.wears).toFixed(2):''])]),'text/csv'));renderWardrobe();

