let lastAgent=null;
$('agentForm').addEventListener('submit',e=>{e.preventDefault();const goal=$('agentGoal').value,tools=$$('#agentForm fieldset input:checked').map(x=>x.value),approval=$('agentApproval').checked,input=$('agentInput').value.trim();const goals={cleanup:'Organise a stream clean-up',market:'Plan a class market day',habitat:'Check a habitat design'};const steps=[`Goal received: ${goals[goal]}. Scope is limited to the class scenario you gave.`,`Scenario read in this browser: “${input}”`,tools.length?`Tools turned on: ${tools.join(', ')}. Each one makes a draft, not an action in the world.`:'No tools turned on. The agent can only ask for a checklist or instructions from a person.',tools.includes('budget')?'Budget model: separate the money you have from what is already committed. Do not assume the stated money is already spent.':'Budget check skipped. A person must work out the resources.',tools.includes('weather')?'Weather tool: open an official forecast link near the event date. No live weather was fetched in this simulation.':'Weather check skipped. Add a human review before an outdoor event.',approval?'Approval gate on: publishing, invitations and spending stop for a teacher or responsible adult.':'Approval gate off in this sketch. The draft is still not published, but this setup would be unsafe in a real system.','Draft complete. No messages sent, bookings made, purchases completed or private data accessed.'];lastAgent={goal:goals[goal],tools,humanApproval:approval,scenario:input,mode:'rule-based classroom simulation',externalActions:false,steps};$('agentSteps').innerHTML=steps.map(s=>`<li>${esc(s)}</li>`).join('');$('agentOutput').innerHTML=`<strong>DRAFT READY FOR A PERSON TO REVIEW</strong><br>${goal==='cleanup'?'Suggested next step: confirm site permission and supervision, then give out safety, equipment and observation roles.':goal==='market'?'Suggested next step: list costs before setting prices, then give out stall, payment practice and clean-up roles.':'Suggested next step: compare each habitat choice with a species-specific source and an animal-care expert.'} ${approval?'No step with real consequences can go ahead without approval.':'Turn the approval gate on before using a design like this outside class.'}`});
