/* ---------------------------------------------------------------- human body systems */
const organs={brain:{system:'Nervous system',title:'Brain',text:'The brain processes information and coordinates responses. Signals travel through the nervous system, and attention, sleep, experience and surroundings all affect how we respond.',connections:'Spinal cord, senses, muscles and every other body system.'},lungs:{system:'Respiratory system',title:'Lungs',text:'Gas exchange happens in the lungs: oxygen moves into the blood and carbon dioxide moves out. Breathing moves the air; the circulatory system carries the gases around the body.',connections:'Heart and blood vessels, diaphragm, muscles and cells.'},heart:{system:'Circulatory system',title:'Heart',text:'The heart pumps blood around the body. Blood carries oxygen, nutrients and other materials, and separate circuits connect the heart to the lungs and to the rest of the body.',connections:'Lungs, blood vessels, kidneys, digestive system and working cells.'},gut:{system:'Digestive system',title:'Digestive system',text:'Digestion breaks food into smaller parts that can be absorbed and used. Mechanical and chemical digestion start in the mouth and continue through the stomach and intestines.',connections:'Blood transport, liver, muscles, nervous system and gut microbes.'},muscle:{system:'Muscular system',title:'Working muscle',text:'Muscles use energy to contract. During activity, their demand for oxygen and their production of carbon dioxide rise, and breathing and circulation respond.',connections:'Lungs, heart, blood, nervous system and nutrients from digestion.'}};
let bodySequence=[],flowRaf=0;
function chooseOrgan(key){const o=organs[key];if(!o)return;$$('.organ').forEach(n=>n.classList.toggle('selected',n.dataset.organ===key));$('bodySystem').textContent=o.system;$('bodyTitle').textContent=o.title;$('bodyText').textContent=o.text;$('bodyConnections').textContent=o.connections}
// oxygenated blood moving lungs → heart → muscle, shown only once the challenge is solved
function bodyFlow(){cancelAnimationFrame(flowRaf);const on=bodySequence.length===3,path=$('bloodPath'),g=$('bloodDots');path.classList.toggle('on',on);if(!on){g.innerHTML='';return}
  const L=path.getTotalLength(),n=6;g.innerHTML=Array.from({length:n},()=>'<circle r="4.5"/>').join('');const dots=[...g.children];
  const place=t=>dots.forEach((c,i)=>{const p=path.getPointAtLength(((t+i/n)%1)*L);c.setAttribute('cx',p.x.toFixed(1));c.setAttribute('cy',p.y.toFixed(1))});
  if(REDUCED()){place(0);return}const t0=performance.now();const step=now=>{if($('panel-body').hidden||bodySequence.length!==3)return;place(((now-t0)/4200)%1);flowRaf=requestAnimationFrame(step)};flowRaf=requestAnimationFrame(step)}
$$('.organ').forEach(n=>{n.addEventListener('click',()=>chooseOrgan(n.dataset.organ));n.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();chooseOrgan(n.dataset.organ)}})});chooseOrgan('brain');
$$('[data-body-step]').forEach(b=>b.addEventListener('click',()=>{const key=b.dataset.bodyStep,expected=['lungs','heart','muscle'][bodySequence.length];chooseOrgan(key);if(key!==expected){bodySequence=[];$$('[data-body-step]').forEach(x=>x.setAttribute('aria-pressed','false'));$('bodyFeedback').textContent='Start again at the lungs: oxygen enters the blood there before the heart pumps it on.';bodyFlow();return}bodySequence.push(key);b.setAttribute('aria-pressed','true');$('bodyFeedback').textContent=bodySequence.length===3?'Complete: lungs → heart → working muscle. Oxygen crosses into the blood in the lungs, the heart pumps that blood, and muscle cells use the oxygen in respiration.':'Correct. Choose the next connection.';bodyFlow()}));
$('resetBody').addEventListener('click',()=>{bodySequence=[];$$('[data-body-step]').forEach(x=>x.setAttribute('aria-pressed','false'));$('bodyFeedback').textContent='Your sequence will appear here.';chooseOrgan('brain');bodyFlow()});

window.addEventListener('pagehide',()=>{if(musicTimer)clearInterval(musicTimer);if(reactionTimer)clearTimeout(reactionTimer);clips.forEach(c=>URL.revokeObjectURL(c.url))});

// open the studio named in the address, if any
const start=location.hash.slice(1);if(tabs.some(t=>t.dataset.tool===start))selectTool(start);else ensureModule('history');
